    path = store_path()
    if not path.exists():
        return empty_store()
    try:
        content = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return empty_store()
    if not isinstance(content, dict):
        return empty_store()
    if any(name in content for name in STORE_COLLECTIONS):
        store = empty_store()
        for name in STORE_COLLECTIONS:
            store[name] = clean_resource_collection(content.get(name))
        return store
    store = empty_store()
    store["meshes"] = clean_resource_collection(content)
    return store


